func BenchmarkEncodeDecodeElementConfig(b *testing.B) {
	seed := v10.ElementConfig{Variant: v10.CapElementConfig{StaticSymbolConfig: fullyPopulatedStaticSymbolConfig}}
	w := orc.NewWriter(0)
	r := orc.NewReader(nil)
	for b.Loop() {
		w.Reset()
		if err := seed.EncodeOrc(w); err != nil {
			b.Fatal(err)
		}
		var decoded v10.ElementConfig
		r.ResetBytes(w.Bytes())
		if err := decoded.DecodeOrc(r); err != nil {
			b.Fatal(err)
		}
	}
}

